// DOM wiring for the browser evidence tool. Depends on evidence.js's globals
// (buildReport, toMarkdown, toJson) and usage.js's (recordUsage, isUsageEnabled,
// setUsageEnabled) being loaded first via plain <script> tags — no bundler, no
// build step, no upload: pasted text never leaves this tab.

function track(eventName) {
  if (typeof recordUsage === "function") recordUsage(eventName);
}

function renderReport(container, report) {
  const rows = report.findings
    .map((finding) => `<tr><td><code>${finding.id}</code></td><td class="status-${finding.status}">${finding.status}</td></tr>`)
    .join("");

  container.innerHTML = `
    <div class="summary-card">
      <div class="summary-stat">
        <span class="summary-number ${report.review_required ? "build-only" : "production"}">${report.review_required ? "yes" : "no"}</span>
        <span class="summary-label">review required</span>
      </div>
      <div class="summary-stat">
        <span class="summary-number">${report.findings.length}</span>
        <span class="summary-label">records compared</span>
      </div>
    </div>
    <div class="report-actions">
      <button type="button" id="download-md">Download Markdown</button>
      <button type="button" id="download-json">Download JSON</button>
    </div>
    <div class="table-wrap">
      <p><strong>Register:</strong> ${report.register}</p>
      <p><strong>Source:</strong> ${report.source_url}</p>
      <p><strong>Captured:</strong> ${report.before_captured_at || "unknown"} &rarr; ${report.after_captured_at || "unknown"}</p>
      <h3>Records</h3>
      <table class="change-table">
        <thead><tr><th>Record</th><th>Status</th></tr></thead>
        <tbody>${rows || "<tr><td colspan=\"2\">no records in either snapshot</td></tr>"}</tbody>
      </table>
      <p class="reason">${report.limitations[0]}</p>
    </div>
  `;

  const download = (blobText, mime, filename, eventName) => {
    const blob = new Blob([blobText], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    track(eventName);
  };

  container.querySelector("#download-md")?.addEventListener("click", () => {
    download(toMarkdown(report), "text/markdown", "public-record-watch.md", "markdown_downloaded");
  });
  container.querySelector("#download-json")?.addEventListener("click", () => {
    download(toJson(report), "application/json", "public-record-watch.json", "json_downloaded");
  });
}

function initApp() {
  const beforeArea = document.getElementById("before-paste");
  const afterArea = document.getElementById("after-paste");
  const compareButton = document.getElementById("compare-button");
  const errorBox = document.getElementById("error");
  const results = document.getElementById("results");
  const optout = document.getElementById("optout");
  const exampleButton = document.getElementById("load-example");

  if (optout && typeof isUsageEnabled === "function" && typeof setUsageEnabled === "function") {
    optout.checked = !isUsageEnabled();
    optout.addEventListener("change", () => setUsageEnabled(!optout.checked));
  }

  function showError(message) {
    errorBox.textContent = message;
    errorBox.hidden = false;
    results.innerHTML = "";
  }

  function runReport(beforeText, afterText) {
    errorBox.hidden = true;
    try {
      const report = buildReport(beforeText, afterText);
      renderReport(results, report);
      track("snapshot_compared");
    } catch (err) {
      showError(err.message || "Could not compare those snapshots.");
      track("compare_failed");
    }
  }

  compareButton?.addEventListener("click", () => {
    const beforeText = beforeArea?.value?.trim();
    const afterText = afterArea?.value?.trim();
    if (!beforeText || !afterText) {
      showError("Paste both a before and an after snapshot first.");
      return;
    }
    runReport(beforeText, afterText);
  });

  // This tool's own example pair — lets a first visit see a real report
  // before assembling snapshots of their own, on the same code path a pasted
  // pair would take (not a separate hard-coded result).
  exampleButton?.addEventListener("click", async () => {
    try {
      const [beforeRes, afterRes] = await Promise.all([
        fetch("examples/before.json"),
        fetch("examples/after.json"),
      ]);
      if (!beforeRes.ok || !afterRes.ok) throw new Error("example unavailable");
      const [beforeText, afterText] = await Promise.all([beforeRes.text(), afterRes.text()]);
      if (beforeArea) beforeArea.value = beforeText.trim();
      if (afterArea) afterArea.value = afterText.trim();
      runReport(beforeText, afterText);
      track("example_used");
    } catch {
      showError("Could not load the bundled example. Paste your own before/after snapshots instead.");
    }
  });
}

if (typeof window !== "undefined") {
  document.addEventListener("DOMContentLoaded", initApp);
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { renderReport };
}

evidence.js.text:
// Pure public-register snapshot comparison logic — no network, no DOM, no
// filesystem. Ports the same rules as
// src/public_record_watch/report.py (the CLI this venture shipped with
// first) so the browser tool and the CLI agree on every verdict.
// Loadable as a plain <script> in the browser (defines globals, no bundler)
// and requireable under `node --test`.

/** Parses and validates one snapshot object. Throws a visitor-facing message. */
function parseSnapshot(text, label) {
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw new Error(`The ${label} snapshot is not valid JSON.`);
  }
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`The ${label} snapshot is not valid JSON.`);
  }
  if (value.authorized !== true) {
    throw new Error(`The ${label} snapshot must declare "authorized": true.`);
  }
  if (typeof value.register !== "string" || !value.register.trim()) {
    throw new Error(`The ${label} snapshot must include a non-empty "register" name.`);
  }
  if (typeof value.source_url !== "string" || !/^https?:\/\//.test(value.source_url)) {
    throw new Error(`The ${label} snapshot's "source_url" must be an http(s) URL.`);
  }
  if (!Array.isArray(value.records)) {
    throw new Error(`The ${label} snapshot must include a "records" list.`);
  }
  const seen = new Set();
  for (const record of value.records) {
    if (!record || typeof record !== "object" || typeof record.id !== "string" || !record.id.trim()) {
      throw new Error(`Every record in the ${label} snapshot must have a non-empty "id".`);
    }
    if (seen.has(record.id)) {
      throw new Error(`The ${label} snapshot contains duplicate record ids ("${record.id}").`);
    }
    seen.add(record.id);
  }
  return value;
}

/** Value used for equality: every field except source_url, order-independent. */
function recordValue(record) {
  const value = {};
  for (const key of Object.keys(record).sort()) {
    if (key === "source_url") continue;
    value[key] = record[key];
  }
  return JSON.stringify(value);
}

/** Compares two validated snapshots. Mirrors report.py's build_report() exactly. */
function compare(before, after) {
  if (before.register !== after.register) {
    throw new Error("Both snapshots must describe the same register.");
  }
  if (before.source_url !== after.source_url) {
    throw new Error("Both snapshots must use the same source_url.");
  }
  const old = new Map(before.records.map((item) => [item.id, item]));
  const next = new Map(after.records.map((item) => [item.id, item]));
  const ids = [...new Set([...old.keys(), ...next.keys()])].sort();
  const findings = ids.map((id) => {
    const previous = old.get(id);
    const current = next.get(id);
    let status;
    if (previous === undefined) status = "added";
    else if (current === undefined) status = "removed";
    else if (recordValue(previous) !== recordValue(current)) status = "changed";
    else status = "unchanged";
    return { id, status, record: current ?? previous };
  });
  const findingCounts = {};
  for (const finding of findings) {
    findingCounts[finding.status] = (findingCounts[finding.status] || 0) + 1;
  }
  return {
    register: before.register,
    source_url: after.source_url,
    before_captured_at: before.captured_at ?? null,
    after_captured_at: after.captured_at ?? null,
    generated_at: new Date().toISOString(),
    finding_counts: findingCounts,
    findings,
    review_required: findings.some((finding) => finding.status !== "unchanged"),
    limitations: [
      "This reports differences between supplied snapshots; it does not establish that a register is complete or current.",
      "A source record is an observation, not a finding that a person is unsuitable, non-compliant, or unsafe.",
      "The customer must verify authorization, source accuracy, and any action before relying on this report.",
    ],
  };
}

/** Builds a report directly from raw before/after snapshot text. */
function buildReport(beforeText, afterText) {
  const before = parseSnapshot(beforeText, "before");
  const after = parseSnapshot(afterText, "after");
  return compare(before, after);
}

function toMarkdown(report) {
  const counts = report.finding_counts;
  const summary = ["added", "removed", "changed", "unchanged"]
    .map((key) => `**${key}:** ${counts[key] || 0}`)
    .join(" · ");
  const lines = [
    `# Public-record changes: \`${report.register}\``,
    "",
    `Source: ${report.source_url}`,
    "",
    "This is a source-linked observation record, not a suitability or compliance determination.",
    "",
    "## Summary",
    "",
    summary,
    "",
    "## Records",
    "",
    "| Record | Status |",
    "|---|---|",
  ];
  for (const finding of report.findings) {
    lines.push(`| \`${finding.id}\` | **${finding.status}** |`);
  }
  lines.push(
    "",
    "## Limits",
    "",
    ...report.limitations.map((item) => `- ${item}`),
    "",
    "**No warranty.** This tool is provided free and as-is, without warranty of any kind, express or implied. It is not legal, tax, financial, medical, or engineering advice, and it does not replace a qualified professional. **You are responsible for reviewing and verifying its output before relying on it**, and for meeting any obligation it helps prepare for. To the maximum extent permitted by law, the authors accept no liability for any loss or damage arising from its use.",
  );
  return lines.join("\n") + "\n";
}

function toJson(report) {
  return JSON.stringify(report, null, 2) + "\n";
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { parseSnapshot, recordValue, compare, buildReport, toMarkdown, toJson };
}

style.css.text:
:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --fg: #1a1a1a;
  --muted: #5f6368;
  --border: #e2e2e2;
  --accent: #2563eb;
  --good: #16a34a;
  --warn: #d97706;
  --card-bg: #f8f9fa;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --fg: #f1f2f4;
    --muted: #9aa0a6;
    --border: #2c2f34;
    --card-bg: #1c1f24;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  line-height: 1.5;
}

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

.hero {
  text-align: center;
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 0.5rem;
}

.tagline {
  color: var(--muted);
  font-size: 1.05rem;
  margin: 0 auto;
  max-width: 56ch;
}

.tagline code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.drop-zone {
  border: 2px dashed var(--border);
  border-radius: 12px;
  padding: 1.75rem 1.25rem;
  text-align: center;
  background: var(--card-bg);
}

.drop-zone p {
  margin: 0.4rem 0 0.9rem;
  color: var(--muted);
}

.snapshot-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  text-align: left;
}

@media (max-width: 560px) {
  .snapshot-grid {
    grid-template-columns: 1fr;
  }
}

.snapshot-col label {
  display: block;
  font-weight: 600;
  font-size: 0.85rem;
  margin-bottom: 0.3rem;
}

.snapshot-col textarea {
  width: 100%;
  font-family: var(--mono);
  font-size: 0.8rem;
  padding: 0.6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  resize: vertical;
}

#compare-button {
  margin-top: 1rem;
  padding: 0.6rem 1.1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

#compare-button:hover {
  filter: brightness(1.08);
}

.example-line {
  text-align: center;
  font-size: 0.95rem;
  opacity: 0.85;
  max-width: 50rem;
  margin: 0.9rem auto 0;
}

.link-button {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
}

.link-button:hover {
  filter: brightness(1.3);
}

.link-button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.error {
  text-align: center;
  color: #dc2626;
  font-weight: 600;
}

.summary-card {
  display: flex;
  justify-content: center;
  gap: 2rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  margin: 1.5rem 0 1rem;
  background: var(--card-bg);
}

.summary-stat {
  text-align: center;
}

.summary-number {
  display: block;
  font-size: 1.6rem;
  font-weight: 800;
  text-transform: capitalize;
}

.summary-number.changed,
.summary-number.build-only { color: var(--warn); }
.summary-number.unchanged,
.summary-number.production { color: var(--good); }
.summary-number.inconclusive { color: #dc2626; }

.summary-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.report-actions {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.report-actions button {
  padding: 0.55rem 1rem;
  font-size: 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
}

.report-actions button:hover {
  border-color: var(--accent);
}

.table-wrap {
  font-size: 0.9rem;
}

.change-list {
  padding-left: 1.25rem;
}

.change-list code {
  font-family: var(--mono);
  font-size: 0.85em;
}

.change-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 0.5rem;
}

.change-table th,
.change-table td {
  text-align: left;
  padding: 0.4rem 0.6rem;
  border-bottom: 1px solid var(--border);
}

.change-table code {
  font-family: var(--mono);
  font-size: 0.85em;
}

.change-table .status-added,
.change-table .status-changed { color: var(--warn); font-weight: 600; }
.change-table .status-removed { color: #dc2626; font-weight: 600; }
.change-table .status-unchanged { color: var(--good); }

.reason {
  color: var(--muted);
}

.disclaimer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  font-size: 0.9rem;
  color: var(--muted);
}

.disclaimer h2 {
  font-size: 1rem;
  color: var(--fg);
}

.disclaimer code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.footer {
  margin-top: 2rem;
  text-align: left;
  font-size: 0.85rem;
  color: var(--muted);
}

.footer p {
  margin: 0.75rem 0;
}

.privacy {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.75rem 0;
}

usage.js.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No snapshot text, no register names, no record
// ids — just an event name and a day, kept in this browser's own
// localStorage. Nothing is sent anywhere; there is no server for it to go
// to. Off-switchable, and honors Do Not Track / Global Privacy Control.

const STORAGE_KEY = "public-record-watch:usage";
const OPT_OUT_KEY = "public-record-watch:usage:off";

function hasStorage() {
  try { return typeof localStorage !== "undefined"; } catch { return false; }
}

function browserOptedOut() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

function isUsageEnabled() {
  if (!hasStorage() || browserOptedOut()) return false;
  try { return localStorage.getItem(OPT_OUT_KEY) !== "1"; } catch { return false; }
}

function setUsageEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch { /* usage must never affect the report */ }
}

function recordUsage(eventName) {
  if (!isUsageEnabled() || !eventName) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const events = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch { /* private browsing and full storage are expected */ }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { isUsageEnabled, setUsageEnabled, recordUsage, STORAGE_KEY, OPT_OUT_KEY };
}
